-- =====================================================================
-- Contenu v3 (26/11/2026) : « Pourquoi le choisir ? » en premier, avantages courts et vérifiés,
-- une seule langue par texte (FR = français, AR = arabe + noms de marque latins, EN = anglais).
-- Remplace une version générée précédemment (v1 ou v2) SEULEMENT si le texte actuel est vide
-- ou identique à cette ancienne version. Un texte modifié dans l'admin n'est JAMAIS écrasé.
-- Ne touche à aucune autre donnée (prix, stock, photos…).
-- Appliqué par : npm run db:migrate, npm run db:seed, npm run db:fiches.
-- =====================================================================

-- fiche: v3-collagen | MEDIHEAL — Collagen (contenu v3) | 
UPDATE products SET
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'من ⁨MEDIHEAL⁩، يأتي ⁨Collagen⁩ في كيس فردي باللونين الوردي والأبيض، مزيَّن برسم لقارورة سيروم. الكولاجين هو نجم هذا المنتج: يشير الغلاف إلى كولاجين بنقاوة 98% وإلى عبارة «⁨Core Firming⁩». ينتمي إلى مجموعة ⁨Mediheal Dermatology⁩، ويحمل عبارة «⁨Dermatology Test Completed⁩».' OR description_ar = 'هل تبحثين عن لحظة دلال؟ يأتيك قناع ⁨Collagen⁩ من ⁨MEDIHEAL⁩ في كيس جميل باللونين الوردي والأبيض. نجمه هو الكولاجين، بنقاوة 98% كما هو مذكور على الغلاف. أضيفيه إلى الباك لاستراحة صغيرة خاصة بك.'
      THEN 'يضع قناع ⁨Collagen⁩ من ⁨MEDIHEAL⁩ الكولاجين في الواجهة: نقاوة 98% كما هو مذكور على الكيس. مختبَر جلدياً، ويأتي في عبوة فردية جاهزة للاستعمال. أضيفيه إلى الباك للحظة خاصة بك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'By MEDIHEAL, Collagen comes in an individual pink-and-white sachet decorated with a serum bottle illustration. Collagen is the star here: the packaging announces 98% purity collagen and the words “Core Firming”. It belongs to the Mediheal Dermatology line and carries the mention “Dermatology Test Completed”.' OR description_en = 'In the mood for a cosy moment? MEDIHEAL''s Collagen mask comes in a pretty pink-and-white sachet. Its star is collagen, with 98% purity stated on the packaging. Slip it into your pack for a little break just for you.'
      THEN 'MEDIHEAL''s Collagen mask puts collagen in the spotlight: 98% purity, as stated on the sachet. Dermatologically tested, it comes as a single mask, ready to use. Slip it into your pack for a moment just for you.' ELSE description_en END,
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Envie d''un moment douceur ? Le masque Collagen de MEDIHEAL t''attend dans son joli sachet rose et blanc. Sa star, c''est le collagène, avec une pureté de 98 % annoncée sur l''emballage. Glisse-le dans ton pack pour une pause rien qu''à toi.' OR description_fr = 'Signé MEDIHEAL, Collagen se présente dans un sachet individuel rose et blanc, orné d''une illustration de flacon de sérum. Le collagène est la star de ce soin : l''emballage annonce un collagène d''une pureté de 98 % et la mention « Core Firming ». Il appartient à la gamme Mediheal Dermatology et porte la mention « Dermatology Test Completed ».'
      THEN 'Le masque Collagen de MEDIHEAL met le collagène à l''honneur : 98 % de pureté, annoncés sur le sachet. Testé dermatologiquement, il se présente en format individuel, prêt à l''emploi. Glisse-le dans ton pack pour un moment rien qu''à toi.' ELSE description_fr END,
  highlights_ar = CASE WHEN highlights_ar IS NULL OR TRIM(highlights_ar) = '' OR highlights_ar = 'النص الكوري: «⁨콜라겐 에센셜 마스크⁩» («⁨Collagen Essential Mask⁩»)\nكولاجين بنقاوة 98% («⁨Purity 98% Collagen⁩»)\nعبارة «⁨Core Firming⁩» مطبوعة على الغلاف\n«⁨Dermatology Test Completed⁩»: تم اختباره جلدياً حسب الغلاف\nمن مجموعة «⁨Mediheal Dermatology⁩» — «⁨Our solution for all⁩»' OR highlights_ar = 'كولاجين بنقاوة 98%: نسبة النقاوة مذكورة بوضوح على الكيس.\nمن توقيع ⁨MEDIHEAL⁩: ضمن مجموعة ⁨Mediheal Dermatology⁩، ومختبَر جلدياً.\nعبوة فردية: قناع في كيسه الخاص، يسهل إضافته إلى الباك.'
      THEN 'الكولاجين في الواجهة: كولاجين بنقاوة 98% كما هو مذكور على الكيس.\nمختبَر جلدياً: قناع من مجموعة ⁨Mediheal Dermatology⁩.\nجاهز في خطوة واحدة: قناع فردي يسهل حمله أو تقديمه هدية.' ELSE highlights_ar END,
  highlights_en = CASE WHEN highlights_en IS NULL OR TRIM(highlights_en) = '' OR highlights_en = '98% pure collagen: the purity level is shown clearly on the sachet.\nSigned MEDIHEAL: part of the Mediheal Dermatology line, dermatologically tested.\nSingle format: one mask in its own sachet, easy to slip into your pack.' OR highlights_en = 'Korean text: “콜라겐 에센셜 마스크” (“Collagen Essential Mask”)\n98% purity collagen (“Purity 98% Collagen”)\n“Core Firming” printed on the sachet\n“Dermatology Test Completed”, as stated on the packaging\n“Mediheal Dermatology” line — “Our solution for all”'
      THEN 'Collagen in the spotlight: 98% pure collagen, as stated on the sachet.\nDermatologically tested: a mask from the Mediheal Dermatology line.\nReady in one step: a single mask, easy to take along or give as a gift.' ELSE highlights_en END,
  highlights_fr = CASE WHEN highlights_fr IS NULL OR TRIM(highlights_fr) = '' OR highlights_fr = 'Collagène pur à 98 % : un taux de pureté affiché clairement sur le sachet.\nSigné MEDIHEAL : un soin de la gamme Mediheal Dermatology, testé dermatologiquement.\nFormat individuel : un masque dans son sachet, facile à glisser dans ton pack.' OR highlights_fr = 'Texte coréen : « 콜라겐 에센셜 마스크 » (« Collagen Essential Mask »)\nCollagène d''une pureté de 98 % (« Purity 98% Collagen »)\nMention « Core Firming » imprimée sur le sachet\n« Dermatology Test Completed » (testé dermatologiquement, selon l''emballage)\nGamme « Mediheal Dermatology » — « Our solution for all »'
      THEN 'Le collagène à l''honneur : un collagène pur à 98 %, indiqué sur le sachet.\nTesté dermatologiquement : un masque de la gamme Mediheal Dermatology.\nPrêt en un geste : un masque individuel, facile à emporter ou à offrir.' ELSE highlights_fr END,
  product_type_ar = CASE WHEN product_type_ar IS NULL OR TRIM(product_type_ar) = '' OR product_type_ar = 'قناع — نوعه بالتحديد (قماشي، جل…) في انتظار التأكيد'
      THEN 'قناع' ELSE product_type_ar END,
  product_type_en = CASE WHEN product_type_en IS NULL OR TRIM(product_type_en) = '' OR product_type_en = 'Mask — exact format (sheet, gel…) to be confirmed'
      THEN 'Mask' ELSE product_type_en END,
  product_type_fr = CASE WHEN product_type_fr IS NULL OR TRIM(product_type_fr) = '' OR product_type_fr = 'Masque — format exact (tissu, gel…) à confirmer'
      THEN 'Masque' ELSE product_type_fr END
WHERE slug = 'collagen'
   OR (TRIM(brand) = 'MEDIHEAL' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Collagen')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%mediheal-collagen%');

-- fiche: v3-vitc | 7th Heaven — Nutriactive Vitamin C Advanced Serum Sheet Mask (contenu v3) | 
UPDATE products SET
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'شعاع شمس صغير في الباك! يأتي هذا القناع القماشي من ⁨7th Heaven⁩ في كيس برتقالي مشرق، ويجمع بين سيروم بفيتامين ⁨C⁩ وورقة قابلة للتحلل الحيوي. مناسب لجميع أنواع البشرة ونباتي (⁨Vegan⁩): اختيار سهل وممتع!' OR description_ar = 'في كيسه البرتقالي المفعم بالحيوية، يجمع قناع ⁨Nutriactive Vitamin C⁩ من ⁨7th Heaven⁩ بين «⁨Advanced Serum⁩» بفيتامين ⁨C⁩ (مركّب نشط بنسبة 5%*) وورقة قابلة للتحلل الحيوي. تقدّمه العلامة كعناية «⁨Anti-Fatigue⁩» — «⁨Brightening + Re-Energising⁩» — لجميع أنواع البشرة، كما يحمل شعار ⁨Vegan⁩ المعتمد من ⁨Vegetarian Society⁩. لمسة برتقالية مبهجة لإضافتها إلى الباك.'
      THEN 'قناع يناسب جميع أنواع البشرة: اختيار سهل! يجمع هذا القناع القماشي من ⁨7th Heaven⁩ بين سيروم بفيتامين سي وورقة قابلة للتحلل الحيوي. وهو نباتي، معتمد من ⁨Vegetarian Society⁩، ويأتي في كيس برتقالي مشرق.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'A ray of sunshine for your pack! This 7th Heaven sheet mask comes in a bright, zesty orange sachet. It pairs a vitamin C serum with a biodegradable sheet. Suitable for all skin types and vegan: easy to love!' OR description_en = 'In its zesty orange sachet, 7th Heaven''s Nutriactive Vitamin C mask pairs an “Advanced Serum” with vitamin C (5% Active Complex*) and a biodegradable sheet. The brand presents it as an “Anti-Fatigue” treatment — “Brightening + Re-Energising” — for all skin types. It also carries the Vegetarian Society Vegan label. A bright splash of orange to add to your pack.'
      THEN 'A mask that suits every skin type: an easy pick! This 7th Heaven sheet mask pairs a vitamin C serum with a biodegradable sheet. It''s vegan, approved by the Vegetarian Society, and comes in a bright orange sachet.' ELSE description_en END,
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Dans son sachet orange vitaminé, le masque Nutriactive Vitamin C de 7th Heaven associe un « Advanced Serum » à la vitamine C (complexe actif à 5 %*) et une feuille biodégradable. La marque le présente comme un soin « Anti-Fatigue » — « Brightening + Re-Energising » — pour tous les types de peau. Il porte aussi le label Vegan de la Vegetarian Society. Une touche d''orange pleine de peps à glisser dans ton pack.' OR description_fr = 'Un rayon de soleil dans ton pack ! Ce masque en tissu 7th Heaven arrive dans un sachet orange tout pétillant. Il associe un sérum à la vitamine C et une feuille biodégradable. Il convient à tous les types de peau et il est vegan : facile à adopter !'
      THEN 'Un masque qui convient à toutes les peaux : un choix facile ! Ce masque en tissu 7th Heaven associe un sérum à la vitamine C et une feuille biodégradable. Il est végan, approuvé par la Vegetarian Society, et arrive dans un sachet orange tout pétillant.' ELSE description_fr END,
  highlights_ar = CASE WHEN highlights_ar IS NULL OR TRIM(highlights_ar) = '' OR highlights_ar = 'سيروم بفيتامين ⁨C⁩: قناع قماشي مرفق بسيروم بفيتامين ⁨C⁩.\nلكل أنواع البشرة: مناسب لجميع أنواع البشرة.\nنباتي (⁨Vegan⁩): معتمد من ⁨Vegetarian Society⁩.\nورقة قابلة للتحلل الحيوي: القناع مصنوع من ورقة قابلة للتحلل الحيوي.' OR highlights_ar = 'فيتامين ⁨C⁩ — مركّب نشط بنسبة 5%* (*توضيح النجمة في انتظار التأكيد، غير مقروء في الصورة)\n«⁨Anti-Fatigue⁩»: «⁨Brightening + Re-Energising⁩» حسب العلامة\nلجميع أنواع البشرة\nنباتي (⁨Vegan⁩) — معتمد من ⁨Vegetarian Society⁩\nورقة قابلة للتحلل الحيوي'
      THEN 'لكل أنواع البشرة: قناع مناسب لجميع أنواع البشرة.\nسيروم بفيتامين سي: ورقة مشبّعة بسيروم بفيتامين سي.\nنباتي: معتمد من ⁨Vegetarian Society⁩.\nورقة قابلة للتحلل الحيوي: القناع مصنوع من ورقة قابلة للتحلل الحيوي.' ELSE highlights_ar END,
  highlights_en = CASE WHEN highlights_en IS NULL OR TRIM(highlights_en) = '' OR highlights_en = 'Vitamin C serum: a sheet mask paired with a vitamin C serum.\nFor every skin type: suitable for all skin types.\nVegan: approved by the Vegetarian Society.\nBiodegradable sheet: the mask is made with a biodegradable sheet.' OR highlights_en = 'Vitamin C — 5% Active Complex* (*asterisk footnote to be confirmed, not legible on the photo)\n“Anti-Fatigue”: “Brightening + Re-Energising”, according to the brand\nFor all skin types\nVegan — Vegetarian Society Approved\nBiodegradable sheet'
      THEN 'Suits every skin: a mask suitable for all skin types.\nVitamin C serum: a sheet soaked in a vitamin C serum.\nVegan: approved by the Vegetarian Society.\nBiodegradable sheet: the mask is made with a biodegradable sheet.' ELSE highlights_en END,
  highlights_fr = CASE WHEN highlights_fr IS NULL OR TRIM(highlights_fr) = '' OR highlights_fr = 'Sérum à la vitamine C : un masque en tissu associé à un sérum à la vitamine C.\nPour toutes les peaux : indiqué pour tous les types de peau.\nVegan : approuvé par la Vegetarian Society.\nFeuille biodégradable : le masque est conçu avec une feuille biodégradable.' OR highlights_fr = 'Vitamine C — complexe actif à 5 %* (*précision de l''astérisque à confirmer, non lisible sur la photo)\n« Anti-Fatigue » : « Brightening + Re-Energising », selon la marque\nPour tous les types de peau\nVegan — approuvé par la Vegetarian Society\nFeuille biodégradable'
      THEN 'Pour toutes les peaux : un masque indiqué pour tous les types de peau.\nSérum à la vitamine C : une feuille imprégnée d''un sérum à la vitamine C.\nVégan : approuvé par la Vegetarian Society.\nFeuille biodégradable : le masque est fait d''une feuille biodégradable.' ELSE highlights_fr END,
  product_type_fr = CASE WHEN product_type_fr IS NULL OR TRIM(product_type_fr) = '' OR product_type_fr = 'Masque en tissu (« sheet mask ») au sérum'
      THEN 'Masque en tissu au sérum' ELSE product_type_fr END
WHERE slug = 'vitc'
   OR (TRIM(brand) = '7th Heaven' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Nutriactive Vitamin C Advanced Serum Sheet Mask')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%7th-heaven-vitamin-c%');

-- fiche: v3-green | look AT ME — Green Blend Tea Tree + Cucumber Face Mask (contenu v3) | 
UPDATE products SET
  content_ar = CASE WHEN content_ar IS NULL OR TRIM(content_ar) = '' OR content_ar = '⁨25 ml / 0.84 fl oz⁩'
      THEN '25 مل' ELSE content_ar END,
  content_fr = CASE WHEN content_fr IS NULL OR TRIM(content_fr) = '' OR content_fr = '25 ml / 0.84 fl oz'
      THEN '25 ml' ELSE content_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'أخضر بالكامل ومليء بالمرح! يجمع قناع ⁨Green Blend⁩ من ⁨look AT ME⁩ بين ثنائي جميل: شجرة الشاي والخيار. بورقته من ألياف ⁨Tencel⁩ وكيسه المرسوم، هو متعة صغيرة تتشاركينها… أو تحتفظين بها لنفسك. صُنع في كوريا، 25 مل.' OR description_ar = 'بغلافه الأخضر المرسوم، يحمل ⁨Green Blend⁩ من ⁨look AT ME⁩ لمسة كورية مميّزة. يجمع هذا القناع للوجه بين شجرة الشاي والخيار على ورقة من ألياف ⁨Tencel⁩، وهو مصنوع في كوريا. تصفه العلامة بعبارة «⁨Revitalizing & Soothing⁩». قناع منعش ومرح لإضافته إلى الباك.'
      THEN 'قناع كوري باللون الأخضر يجمع ثنائياً نباتياً: شجرة الشاي والخيار. صُنع في كوريا، ويأتي على ورقة من ألياف ⁨Tencel⁩ في كيس مرسوم مليء بالمرح. متعة صغيرة تتشاركينها… أو تحتفظين بها لنفسك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'All green and full of good vibes! look AT ME''s Green Blend mask brings together a lovely duo: tea tree and cucumber. With its Tencel sheet and illustrated sachet, it''s a little treat to share… or keep all to yourself. Made in Korea, 25 ml.' OR description_en = 'With its all-green illustrated sachet, look AT ME''s Green Blend has real Korean charm. This face mask brings together tea tree and cucumber on a Tencel sheet, and it is made in Korea. The brand describes it as “Revitalizing & Soothing”. A fresh, playful mask to add to your pack.'
      THEN 'An all-green Korean mask with a plant duo: tea tree and cucumber. Made in Korea, it comes on a Tencel sheet, in a cheerful illustrated sachet. A little treat to share… or keep all to yourself.' ELSE description_en END,
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Avec son sachet illustré tout en vert, Green Blend de look AT ME a un vrai charme coréen. Ce masque visage réunit l''arbre à thé et le concombre sur une feuille en Tencel, et il est fabriqué en Corée. La marque le décrit comme « Revitalizing & Soothing ». Un masque frais et ludique à ajouter à ton pack.' OR description_fr = 'Tout en vert et plein de bonne humeur ! Le masque Green Blend de look AT ME réunit un joli duo : l''arbre à thé et le concombre. Avec sa feuille en Tencel et son sachet illustré, c''est un petit plaisir à partager… ou à garder pour toi. Fabriqué en Corée, 25 ml.'
      THEN 'Un masque coréen tout en vert, avec un duo végétal : l''arbre à thé et le concombre. Fabriqué en Corée, il se présente sur une feuille en Tencel, dans un sachet illustré plein de bonne humeur. Un petit plaisir à partager… ou à garder pour toi.' ELSE description_fr END,
  highlights_ar = CASE WHEN highlights_ar IS NULL OR TRIM(highlights_ar) = '' OR highlights_ar = 'شجرة الشاي + الخيار («⁨Tea Tree + Cucumber⁩»)\n«⁨Revitalizing & Soothing⁩» حسب العلامة\nورقة من ألياف ⁨Tencel⁩\nصُنع في كوريا («⁨Made in Korea⁩»)' OR highlights_ar = 'شجرة الشاي والخيار: ثنائي من المكوّنات يبرز منذ اسم المنتج.\nورقة من ألياف ⁨Tencel⁩: قناع للوجه على ورقة من ألياف ⁨Tencel⁩.\nصُنع في كوريا: قناع كوري بكيس مرسوم مليء بالسحر.\nعبوة 25 مل: قناع فردي جاهز للاستعمال.'
      THEN 'ثنائي نباتي: شجرة الشاي والخيار في قناع واحد.\nصُنع في كوريا: قناع كوري بكيس مرسوم.\nورقة من ألياف ⁨Tencel⁩: قناع للوجه على ورقة من ألياف ⁨Tencel⁩.\nجاهز للاستعمال: قناع فردي بحجم 25 مل.' ELSE highlights_ar END,
  highlights_en = CASE WHEN highlights_en IS NULL OR TRIM(highlights_en) = '' OR highlights_en = 'Tea Tree + Cucumber\n“Revitalizing & Soothing”, according to the brand\nTencel sheet\nMade in Korea' OR highlights_en = 'Tea tree & cucumber: a duo of ingredients featured right in the name.\nTencel sheet: a face mask on a Tencel sheet.\nMade in Korea: a Korean mask with a charming illustrated sachet.\n25 ml format: a single mask, ready to use.'
      THEN 'A plant duo: tea tree and cucumber, together in one mask.\nMade in Korea: a Korean mask with an illustrated sachet.\nTencel sheet: a face mask on a Tencel sheet.\nReady to use: a single 25 ml mask.' ELSE highlights_en END,
  highlights_fr = CASE WHEN highlights_fr IS NULL OR TRIM(highlights_fr) = '' OR highlights_fr = 'Arbre à thé & concombre : un duo d''ingrédients mis en avant dès le nom.\nFeuille en Tencel : un masque visage sur une feuille en Tencel.\nFabriqué en Corée : un masque coréen au sachet illustré plein de charme.\nFormat 25 ml : un masque individuel, prêt à l''emploi.' OR highlights_fr = 'Arbre à thé + concombre (« Tea Tree + Cucumber »)\n« Revitalizing & Soothing », selon la marque\nFeuille en Tencel (« Tencel sheet »)\nFabriqué en Corée (« Made in Korea »)'
      THEN 'Un duo végétal : l''arbre à thé et le concombre, réunis dans un même masque.\nFabriqué en Corée : un masque coréen au sachet illustré.\nFeuille en Tencel : un masque visage sur une feuille en Tencel.\nPrêt à l''emploi : un masque individuel de 25 ml.' ELSE highlights_fr END
WHERE slug = 'green'
   OR (TRIM(brand) = 'look AT ME' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Green Blend Tea Tree + Cucumber Face Mask')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%lookatme-green-blend%');

-- fiche: v3-hazel | IDC Institute — One Week Treatment — Hazel + Lavender (contenu v3) | 
UPDATE products SET
  content_ar = CASE WHEN content_ar IS NULL OR TRIM(content_ar) = '' OR content_ar = '⁨22 g / 0.73 fl.oz⁩'
      THEN '22 غرام' ELSE content_ar END,
  content_fr = CASE WHEN content_fr IS NULL OR TRIM(content_fr) = '' OR content_fr = '22 g / 0.73 fl.oz'
      THEN '22 g' ELSE content_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'الأربعاء هو يومه! يحمل هذا القناع من ⁨IDC Institute⁩ الرقم 3 في مجموعة ⁨One Week Treatment⁩، «⁨Wednesday⁩». يجمع بين الهماميليس واللافندر في كيس أنيق بلونَي البنفسجي والفضي، وهو أيضاً ⁨Cruelty free⁩.' OR description_ar = 'ينتمي هذا القناع إلى مجموعة «⁨One Week Treatment⁩» من ⁨IDC Institute⁩: إنه القناع رقم 3، «⁨Wednesday⁩» (الأربعاء)، في كيس بلونَي البنفسجي والفضي. يجمع بين الهماميليس واللافندر، وترفقه العلامة بعبارة «ينظّف مسام البشرة ويزيل عنها التعب». ويحمل الغلاف شعار ⁨Cruelty free⁩.'
      THEN 'موعد جمال كل أربعاء؟ هذا القناع من ⁨IDC Institute⁩ هو الرقم 3 في مجموعة ⁨One Week Treatment⁩: قناع يوم الأربعاء. يجمع بين الهماميليس واللافندر في كيس أنيق بلونَي البنفسجي والفضي، وهو غير مختبَر على الحيوانات.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'This mask belongs to IDC Institute''s “One Week Treatment” line: it is no. 3, “Wednesday”, in a purple and silver sachet. It combines witch hazel and lavender, and the brand adds the text “Clean the pore of skin and remove fatique from your face”. The packaging displays the Cruelty free logo.' OR description_en = 'Wednesday is its day! This IDC Institute facial mask is no. 3 in the One Week Treatment line, “Wednesday”. It brings together witch hazel and lavender in a pretty purple and silver sachet. And it''s cruelty free, too.'
      THEN 'Fancy a Wednesday beauty date? This IDC Institute facial mask is no. 3 in the One Week Treatment line: the Wednesday one. It brings together witch hazel and lavender in a pretty purple and silver sachet. And it''s cruelty free.' ELSE description_en END,
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Ce masque fait partie de la gamme « One Week Treatment » d''IDC Institute : c''est le n°3, « Wednesday » (mercredi), dans un sachet violet et argent. Il associe l''hamamélis et la lavande, et la marque l''accompagne du texte « Nettoie les pores et élimine la fatigue de la peau ». L''emballage affiche le logo Cruelty free.' OR description_fr = 'Mercredi, c''est son jour ! Ce masque visage IDC Institute porte le n°3 de la gamme One Week Treatment, « Wednesday ». Il réunit l''hamamélis et la lavande dans un joli sachet violet et argent. Et en plus, il est cruelty free.'
      THEN 'Un rendez-vous beauté chaque mercredi ? Ce masque visage IDC Institute est le n°3 de la gamme One Week Treatment : celui du mercredi. Il réunit l''hamamélis et la lavande dans un joli sachet violet et argent. Et il n''est pas testé sur les animaux.' ELSE description_fr END,
  highlights_ar = CASE WHEN highlights_ar IS NULL OR TRIM(highlights_ar) = '' OR highlights_ar = 'مجموعة «⁨One Week Treatment⁩» — القناع رقم 3، «⁨Wednesday⁩» (الأربعاء)\nالهماميليس واللافندر («⁨Hazel + Lavender⁩»)\n«ينظّف مسام البشرة ويزيل عنها التعب» — نص مطبوع من العلامة\nشعار «⁨Cruelty free⁩»' OR highlights_ar = 'مجموعة ⁨One Week Treatment⁩: القناع رقم 3، قناع يوم الأربعاء («⁨Wednesday⁩»).\nالهماميليس واللافندر: مكوّنان بارزان على الكيس.\n⁨Cruelty free⁩: الشعار ظاهر على الغلاف.\nعبوة 22 غرام: قناع فردي للوجه.'
      THEN 'قناع يوم الأربعاء: القناع رقم 3 من مجموعة ⁨One Week Treatment⁩.\nالهماميليس واللافندر: مكوّنان بارزان على الكيس.\nغير مختبَر على الحيوانات: الشعار ظاهر على الغلاف.\nجاهز للاستعمال: قناع فردي للوجه بوزن 22 غرام.' ELSE highlights_ar END,
  highlights_en = CASE WHEN highlights_en IS NULL OR TRIM(highlights_en) = '' OR highlights_en = 'One Week Treatment line: mask no. 3, the Wednesday one.\nWitch hazel & lavender: two ingredients featured on the sachet.\nCruelty free: the logo is shown on the packaging.\n22 g format: a single facial mask.' OR highlights_en = '“One Week Treatment” line — mask no. 3, “Wednesday”\nHazel + Lavender (witch hazel and lavender)\n“Clean the pore of skin and remove fatique from your face” — text printed by the brand (spelling as printed)\n“Cruelty free” logo'
      THEN 'The Wednesday mask: no. 3 in the One Week Treatment line.\nWitch hazel and lavender: two ingredients featured on the sachet.\nCruelty free: the logo is shown on the packaging.\nReady to use: a single 22 g facial mask.' ELSE highlights_en END,
  highlights_fr = CASE WHEN highlights_fr IS NULL OR TRIM(highlights_fr) = '' OR highlights_fr = 'Gamme One Week Treatment : le masque n°3, celui du mercredi (« Wednesday »).\nHamamélis & lavande : deux ingrédients mis en avant sur le sachet.\nCruelty free : le logo est affiché sur l''emballage.\nFormat 22 g : un masque visage individuel.' OR highlights_fr = 'Gamme « One Week Treatment » — masque n°3, « Wednesday » (mercredi)\nHamamélis + lavande (« Hazel + Lavender »)\n« Nettoie les pores et élimine la fatigue de la peau » — texte imprimé par la marque\nLogo « Cruelty free »'
      THEN 'Le masque du mercredi : le n°3 de la gamme One Week Treatment.\nHamamélis et lavande : deux ingrédients mis en avant sur le sachet.\nNon testé sur les animaux : le logo figure sur l''emballage.\nPrêt à l''emploi : un masque visage individuel de 22 g.' ELSE highlights_fr END,
  product_type_ar = CASE WHEN product_type_ar IS NULL OR TRIM(product_type_ar) = '' OR product_type_ar = 'قناع للوجه («⁨Facial Mask⁩»)'
      THEN 'قناع للوجه' ELSE product_type_ar END,
  product_type_fr = CASE WHEN product_type_fr IS NULL OR TRIM(product_type_fr) = '' OR product_type_fr = 'Masque visage (« Facial Mask »)'
      THEN 'Masque visage' ELSE product_type_fr END
WHERE slug = 'hazel'
   OR (TRIM(brand) = 'IDC Institute' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'One Week Treatment - Hazel + Lavender')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%idc-hazel-lavender%');

-- fiche: v3-gluta | SOME BY MI — Real Glutathione Brightening Care Mask (contenu v3) | 
UPDATE products SET
  content_ar = CASE WHEN content_ar IS NULL OR TRIM(content_ar) = '' OR content_ar = 'الوزن الصافي ⁨20 g – 0.70 oz⁩'
      THEN 'الوزن الصافي: 20 غرام' ELSE content_ar END,
  content_fr = CASE WHEN content_fr IS NULL OR TRIM(content_fr) = '' OR content_fr = 'Net 20 g – 0.70 oz'
      THEN 'Poids net : 20 g' ELSE content_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'بسيط وأنيق ومليء بالفقاعات الوردية! قناع ⁨Real Glutathione⁩ من ⁨SOME BY MI⁩ مركّب بالغلوتاثيون، على ورقة نباتية 100% وقابلة للتحلل الحيوي. مختبَر جلدياً، وسيجد مكانه بسرعة في الباك.' OR description_ar = 'في كيس أنيق تزيّنه فقاعات وردية، يأتي ⁨Real Glutathione Brightening Care Mask⁩ من ⁨SOME BY MI⁩: قناع بورقة نباتية 100% وقابلة للتحلل الحيوي، مركّب بالغلوتاثيون. وبحسب النص المطبوع على الغلاف، فهو «يُنعش البشرة الباهتة ويساعد على الحصول على بشرة أكثر إشراقاً وتجانساً في اللون». وترفقه العلامة بعبارتي «⁨Moisturizing | Radiance⁩» و«⁨Dermatologist Tested⁩».'
      THEN 'قناع أنيق يضع الغلوتاثيون في الواجهة! قناع ⁨Real Glutathione⁩ من ⁨SOME BY MI⁩ مختبَر جلدياً، ويأتي على ورقة نباتية 100% وقابلة للتحلل الحيوي. وسيجد كيسه المزيّن بالفقاعات الوردية مكانه بسرعة في الباك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'In a clean sachet with pink bubbles, SOME BY MI''s Real Glutathione Brightening Care Mask is a 100% plant-based biodegradable sheet mask formulated with Real Glutathione. According to the packaging, it “revitalizes dull skin and promotes a brighter, more even skin tone”. The brand adds the mentions “Moisturizing | Radiance” and “Dermatologist Tested”.' OR description_en = 'Simple, elegant and full of pink bubbles! SOME BY MI''s Real Glutathione mask is formulated with glutathione, on a 100% plant-based, biodegradable sheet. Dermatologist tested, it will soon find its place in your pack.'
      THEN 'An elegant mask that puts glutathione in the spotlight! SOME BY MI''s Real Glutathione is dermatologically tested and comes on a 100% plant-based, biodegradable sheet. Its pink-bubble sachet will soon find its place in your pack.' ELSE description_en END,
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Dans un sachet épuré aux bulles roses, Real Glutathione Brightening Care Mask de SOME BY MI est un masque à feuille 100 % d''origine végétale et biodégradable, formulé avec du glutathion. D''après le texte de l''emballage, il « redonne de la vitalité aux peaux ternes et favorise un teint plus lumineux et plus uniforme ». La marque l''accompagne des mentions « Moisturizing | Radiance » et « Dermatologist Tested ».' OR description_fr = 'Simple, élégant et tout en bulles roses ! Le masque Real Glutathione de SOME BY MI est formulé avec du glutathion, sur une feuille 100 % végétale et biodégradable. Testé dermatologiquement, il trouvera vite sa place dans ton pack.'
      THEN 'Un masque élégant qui met le glutathion à l''honneur ! Le Real Glutathione de SOME BY MI est testé dermatologiquement et se présente sur une feuille 100 % végétale et biodégradable. Son sachet tout en bulles roses trouvera vite sa place dans ton pack.' ELSE description_fr END,
  highlights_ar = CASE WHEN highlights_ar IS NULL OR TRIM(highlights_ar) = '' OR highlights_ar = 'بالغلوتاثيون: المكوّن النجم، يبرز منذ اسم المنتج.\nورقة نباتية 100%: من أصل نباتي وقابلة للتحلل الحيوي.\nمختبَر جلدياً: عبارة ظاهرة على الكيس.\nعبوة 20 غرام: قناع قماشي فردي.' OR highlights_ar = 'مركّب بالغلوتاثيون («⁨Real Glutathione⁩»)\n«⁨Moisturizing | Radiance⁩» حسب العلامة\n«⁨Clinical Solution — Dermatologist Tested⁩»\nورقة نباتية 100% وقابلة للتحلل الحيوي'
      THEN 'الغلوتاثيون في الواجهة: المكوّن النجم، منذ اسم القناع.\nمختبَر جلدياً: عبارة ظاهرة على الكيس.\nورقة نباتية 100%: من أصل نباتي وقابلة للتحلل الحيوي.\nجاهز للاستعمال: قناع قماشي فردي بوزن 20 غرام.' ELSE highlights_ar END,
  highlights_en = CASE WHEN highlights_en IS NULL OR TRIM(highlights_en) = '' OR highlights_en = 'Formulated with Real Glutathione\n“Moisturizing | Radiance”, according to the brand\n“Clinical Solution — Dermatologist Tested”\n100% plant-based biodegradable sheet' OR highlights_en = 'With glutathione: the star ingredient, featured right in the name.\n100% plant-based sheet: plant-based and biodegradable.\nDermatologically tested: a mention shown on the sachet.\n20 g format: a single sheet mask.'
      THEN 'Glutathione in the spotlight: the star ingredient, right in the mask''s name.\nDermatologically tested: a mention shown on the sachet.\n100% plant-based sheet: plant-based and biodegradable.\nReady to use: a single 20 g sheet mask.' ELSE highlights_en END,
  highlights_fr = CASE WHEN highlights_fr IS NULL OR TRIM(highlights_fr) = '' OR highlights_fr = 'Au glutathion : l''ingrédient vedette, mis en avant dès le nom.\nFeuille 100 % végétale : d''origine végétale et biodégradable.\nTesté dermatologiquement : une mention affichée sur le sachet.\nFormat 20 g : un masque en tissu individuel.' OR highlights_fr = 'Formulé avec du « Real Glutathione » (glutathion)\n« Moisturizing | Radiance », selon la marque\n« Clinical Solution — Dermatologist Tested »\nFeuille 100 % d''origine végétale et biodégradable'
      THEN 'Le glutathion à l''honneur : l''ingrédient vedette, dès le nom du masque.\nTesté dermatologiquement : une mention affichée sur le sachet.\nFeuille 100 % végétale : d''origine végétale et biodégradable.\nPrêt à l''emploi : un masque en tissu individuel de 20 g.' ELSE highlights_fr END
WHERE slug = 'gluta'
   OR (TRIM(brand) = 'SOME BY MI' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Real Glutathione Brightening Care Mask')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%some-by-mi-glutathione%');

-- fiche: v3-rosegold | masque BAR — Rose Gold Foil Sheet Mask (contenu v3) | 
UPDATE products SET
  content_ar = CASE WHEN content_ar IS NULL OR TRIM(content_ar) = '' OR content_ar = 'قناع كامل واحد — ⁨30 ml / 1.01 US fl oz⁩'
      THEN 'قناع كامل واحد — 30 مل' ELSE content_ar END,
  content_fr = CASE WHEN content_fr IS NULL OR TRIM(content_fr) = '' OR content_fr = '1 masque complet — 30 ml / 1.01 US fl oz'
      THEN '1 masque complet — 30 ml' ELSE content_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'بكيسه الأنيق بلون الذهب الوردي، يضيف ⁨Rose Gold Foil Sheet Mask⁩ من ⁨masque BAR⁩ (⁨Unmasque Beauty⁩) لمسة راقية إلى الباك. وبحسب الغلاف، فهو «غني بمستخلصات تساعد على تغذية البشرة وترطيبها»، ويبرز مستخلص فول الصويا ومستخلص الفطر وماء الهماميليس.' OR description_ar = 'لمسة فخامة في الباك! يتألق قناع ⁨Rose Gold Foil Sheet Mask⁩ من ⁨masque BAR⁩ في كيسه بلون الذهب الوردي. في الداخل: قناع كامل بحجم 30 مل، بمستخلص فول الصويا ومستخلص الفطر وماء الهماميليس. مثالي لسهرة دلال مع الصديقات… أو بمفردك.'
      THEN 'لمسة فخامة في الباك! يجمع قناع ⁨Rose Gold Foil Sheet Mask⁩ من ⁨masque BAR⁩ ثلاثة مستخلصات: فول الصويا والفطر وماء الهماميليس. هو قناع كامل بحجم 30 مل، في كيس لامع بلون الذهب الوردي. مثالي لسهرة دلال مع الصديقات… أو بمفردك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'A touch of glam for your pack! masque BAR''s Rose Gold Foil Sheet Mask shines in its rose-gold sachet. Inside: one complete 30 ml mask with soybean extract, mushroom extract and witch hazel water. Ideal for a cosy night in with friends… or solo.' OR description_en = 'With its elegant rose-gold sachet, masque BAR''s Rose Gold Foil Sheet Mask (Unmasque Beauty) brings a chic touch to your pack. According to the packaging, it is “enriched with extracts that help nourish and hydrate your skin” and highlights soybean extract, mushroom extract and witch hazel water.'
      THEN 'A touch of glam for your pack! masque BAR''s Rose Gold Foil Sheet Mask brings together three extracts: soybean, mushroom and witch hazel water. It''s one complete 30 ml mask, in a shiny rose-gold sachet. Ideal for a cosy night in with friends… or solo.' ELSE description_en END,
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Avec son sachet élégant aux reflets rose doré, le Rose Gold Foil Sheet Mask de masque BAR (Unmasque Beauty) apporte une touche chic à ton pack. D''après l''emballage, il est « enrichi d''extraits qui aident à nourrir et hydrater la peau » et met en avant l''extrait de soja, l''extrait de champignon et l''eau d''hamamélis.' OR description_fr = 'Une touche de glamour dans ton pack ! Le Rose Gold Foil Sheet Mask de masque BAR brille dans son sachet rose doré. À l''intérieur : un masque complet de 30 ml, avec extrait de soja, extrait de champignon et eau d''hamamélis. Idéal pour une soirée cocooning entre copines… ou en solo.'
      THEN 'Une touche de glamour dans ton pack ! Le Rose Gold Foil Sheet Mask de masque BAR réunit trois extraits : soja, champignon et eau d''hamamélis. C''est un masque complet de 30 ml, dans un sachet rose doré qui brille. Idéal pour une soirée douceur entre copines… ou en solo.' ELSE description_fr END,
  highlights_ar = CASE WHEN highlights_ar IS NULL OR TRIM(highlights_ar) = '' OR highlights_ar = 'الصويا والفطر والهماميليس: ثلاثة مستخلصات بارزة على الكيس.\nقناع كامل بحجم 30 مل: عبوة فردية جاهزة للاستعمال.\nلمسة الذهب الوردي: كيس أنيق من خط ⁨Unmasque Beauty⁩.' OR highlights_ar = 'يحتوي على: مستخلص فول الصويا، مستخلص الفطر، ماء الهماميليس (مكوّنات بارزة على الغلاف — القائمة الكاملة في انتظار التأكيد)\n«غني بمستخلصات تساعد على تغذية البشرة وترطيبها» — نص العلامة\nخط «⁨Unmasque Beauty⁩»'
      THEN 'ثلاثة مستخلصات: الصويا والفطر والهماميليس، بارزة على الكيس.\nقناع كامل: عبوة فردية بحجم 30 مل جاهزة للاستعمال.\nلمسة أنيقة: كيس بلون الذهب الوردي من خط ⁨Unmasque Beauty⁩.' ELSE highlights_ar END,
  highlights_en = CASE WHEN highlights_en IS NULL OR TRIM(highlights_en) = '' OR highlights_en = 'Contains: Soybean Extract, Mushroom Extract, Witch Hazel Water (ingredients highlighted on the packaging — full list to be confirmed)\n“Enriched with extracts that help nourish and hydrate your skin” — brand text\n“Unmasque Beauty” line' OR highlights_en = 'Soybean, mushroom & witch hazel: three extracts featured on the sachet.\nComplete 30 ml mask: a single format, ready to use.\nRose-gold style: an elegant sachet from the Unmasque Beauty line.'
      THEN 'Three extracts: soybean, mushroom and witch hazel, featured on the sachet.\nA complete mask: a single 30 ml format, ready to use.\nA chic touch: a rose-gold sachet from the Unmasque Beauty line.' ELSE highlights_en END,
  highlights_fr = CASE WHEN highlights_fr IS NULL OR TRIM(highlights_fr) = '' OR highlights_fr = 'Contient : extrait de soja, extrait de champignon, eau d''hamamélis (ingrédients mis en avant sur l''emballage — liste complète à confirmer)\n« Enrichi d''extraits qui aident à nourrir et hydrater la peau » — texte de la marque\nLigne « Unmasque Beauty »' OR highlights_fr = 'Soja, champignon & hamamélis : trois extraits mis en avant sur le sachet.\nMasque complet de 30 ml : un format individuel, prêt à l''emploi.\nStyle rose doré : un sachet élégant de la ligne Unmasque Beauty.'
      THEN 'Trois extraits : soja, champignon et hamamélis, mis en avant sur le sachet.\nUn masque complet : un format individuel de 30 ml, prêt à l''emploi.\nUne touche chic : un sachet rose doré de la ligne Unmasque Beauty.' ELSE highlights_fr END,
  product_type_fr = CASE WHEN product_type_fr IS NULL OR TRIM(product_type_fr) = '' OR product_type_fr = 'Masque en tissu (« sheet mask »)'
      THEN 'Masque en tissu' ELSE product_type_fr END
WHERE slug = 'rosegold'
   OR (TRIM(brand) = 'masque BAR' AND REPLACE(REPLACE(TRIM(name), '—', '-'), '–', '-') = 'Rose Gold Foil Sheet Mask')
   OR EXISTS (SELECT 1 FROM product_images i WHERE i.product_id = products.id AND i.url LIKE '%masquebar-rose-gold-foil%');

-- fiche: v3-orjena-power-collagen-emulsion | ORJENA — Power Collagen Emulsion (contenu v3) | 
UPDATE products SET
  content_ar = CASE WHEN content_ar IS NULL OR TRIM(content_ar) = '' OR content_ar = '⁨100 ml / 3.38 fl oz⁩'
      THEN '100 مل' ELSE content_ar END,
  content_fr = CASE WHEN content_fr IS NULL OR TRIM(content_fr) = '' OR content_fr = '100 ml / 3.38 fl oz'
      THEN '100 ml' ELSE content_fr END,
  description_ar = CASE WHEN description_ar IS NULL OR TRIM(description_ar) = '' OR description_ar = 'في قارورتها العنابية ذات الغطاء الفضي، تضع ⁨Power Collagen Emulsion⁩ من ⁨ORJENA⁩ الكولاجين في الواجهة منذ اسمها. تقدّمها العلامة من خلال ثلاث عبارات مطبوعة على العلبة — «⁨Skin Elasticity⁩» و«⁨Skin Nutrition⁩» و«⁨Refresh⁩» — وهي مناسبة لجميع أنواع البشرة. خطوة لطيفة تضيفينها إلى روتينك مباشرة بعد التنظيف واستعمال التونر.' OR description_ar = 'قارورة عنابية أنيقة ومستحلب بالكولاجين: ⁨Power Collagen Emulsion⁩ من ⁨ORJENA⁩ فيها كل ما يعجبك! مناسبة لجميع أنواع البشرة، وتندمج بسهولة في روتينك مباشرة بعد التنظيف والتونر. 100 مل لتبقى دائماً في متناول يدك.'
      THEN 'مستحلب يناسب جميع أنواع البشرة، والكولاجين في الواجهة! يندمج ⁨Power Collagen Emulsion⁩ من ⁨ORJENA⁩ بسهولة في روتينك، مباشرة بعد التنظيف والتونر. وتبقى قارورته العنابية الأنيقة بحجم 100 مل دائماً في متناول يدك.' ELSE description_ar END,
  description_en = CASE WHEN description_en IS NULL OR TRIM(description_en) = '' OR description_en = 'A chic burgundy bottle and a collagen emulsion: ORJENA''s Power Collagen Emulsion has everything to win you over! Suitable for all skin types, it slips easily into your routine, right after cleansing and toning. 100 ml to keep close at hand.' OR description_en = 'In its burgundy bottle with a silver cap, ORJENA''s Power Collagen Emulsion puts collagen in the spotlight right from its name. The brand presents it with three mentions printed on the packaging — “Skin Elasticity”, “Skin Nutrition” and “Refresh” — and recommends it for all skin types. A gentle step to add to your routine, right after cleansing and toning.'
      THEN 'An emulsion that suits all skin types, with collagen in the spotlight! ORJENA''s Power Collagen Emulsion slips easily into your routine, right after cleansing and toning. Its chic 100 ml burgundy bottle stays close at hand.' ELSE description_en END,
  description_fr = CASE WHEN description_fr IS NULL OR TRIM(description_fr) = '' OR description_fr = 'Dans son flacon bordeaux au bouchon argenté, Power Collagen Emulsion d''ORJENA est une émulsion qui met le collagène à l''honneur dès son nom. La marque la présente autour de trois mentions imprimées sur l''emballage — « Skin Elasticity », « Skin Nutrition » et « Refresh » — et l''indique pour tous les types de peau. Un geste tout en douceur à glisser dans ta routine, juste après le nettoyage et la tonification.' OR description_fr = 'Un flacon bordeaux chic et une émulsion au collagène : Power Collagen Emulsion d''ORJENA a tout pour te plaire ! Elle convient à tous les types de peau et se glisse facilement dans ta routine, juste après le nettoyage et le tonique. 100 ml à garder à portée de main.'
      THEN 'Une émulsion qui convient à tous les types de peau, avec le collagène à l''honneur ! Power Collagen Emulsion d''ORJENA se glisse facilement dans ta routine, juste après le nettoyage et le tonique. Son flacon bordeaux chic de 100 ml se garde à portée de main.' ELSE description_fr END,
  highlights_ar = CASE WHEN highlights_ar IS NULL OR TRIM(highlights_ar) = '' OR highlights_ar = '«⁨Skin Elasticity⁩» (مرونة البشرة) — عبارة مطبوعة على العلبة\n«⁨Skin Nutrition⁩» (تغذية البشرة) — عبارة مطبوعة على العلبة\n«⁨Refresh⁩» (الانتعاش) — عبارة مطبوعة على العلبة\nلجميع أنواع البشرة («⁨For all skin types⁩»)' OR highlights_ar = 'بالكولاجين: يبرز الكولاجين منذ اسم المستحلب.\nلكل أنواع البشرة: مناسب لجميع أنواع البشرة.\nسهل الإدماج في روتينك: يُطبَّق مباشرة بعد التنظيف والتونر.\nقارورة 100 مل: حجم كبير يبقى دائماً في متناول يدك.'
      THEN 'لكل أنواع البشرة: مستحلب مناسب لجميع أنواع البشرة.\nالكولاجين في الواجهة: يبرز منذ اسم المستحلب.\nسهل الاستعمال: يُطبَّق مباشرة بعد التنظيف والتونر.\nحجم كبير: قارورة 100 مل تبقى في متناول يدك.' ELSE highlights_ar END,
  highlights_en = CASE WHEN highlights_en IS NULL OR TRIM(highlights_en) = '' OR highlights_en = 'With collagen: collagen is featured right in the emulsion''s name.\nFor every skin type: suitable for all skin types.\nEasy to add: applied right after cleansing and toning.\n100 ml bottle: a large size to keep close at hand.' OR highlights_en = '“Skin Elasticity” — printed on the packaging\n“Skin Nutrition” — printed on the packaging\n“Refresh” — printed on the packaging\nFor all skin types'
      THEN 'For every skin type: an emulsion suitable for all skin types.\nCollagen in the spotlight: featured right in the emulsion''s name.\nEasy to adopt: applied right after cleansing and toning.\nLarge size: a 100 ml bottle to keep close at hand.' ELSE highlights_en END,
  highlights_fr = CASE WHEN highlights_fr IS NULL OR TRIM(highlights_fr) = '' OR highlights_fr = 'Au collagène : le collagène est mis en avant dès le nom de l''émulsion.\nPour toutes les peaux : indiquée pour tous les types de peau.\nFacile à intégrer : s''applique juste après le nettoyage et le tonique.\nFlacon de 100 ml : un grand format à garder à portée de main.' OR highlights_fr = '« Skin Elasticity » (élasticité de la peau) — mention de l''emballage\n« Skin Nutrition » (nutrition de la peau) — mention de l''emballage\n« Refresh » (fraîcheur) — mention de l''emballage\nPour tous les types de peau (« For all skin types »)'
      THEN 'Pour toutes les peaux : une émulsion indiquée pour tous les types de peau.\nLe collagène à l''honneur : mis en avant dès le nom de l''émulsion.\nFacile à adopter : s''applique juste après le nettoyage et le tonique.\nGrand format : un flacon de 100 ml à garder à portée de main.' ELSE highlights_fr END
WHERE slug = 'orjena-power-collagen-emulsion' OR (TRIM(brand) = 'ORJENA' AND TRIM(name) = 'Power Collagen Emulsion');

